"""The sounds of a take (DictationSound.swift): generated by assets/sounds/build.py, short, and copied into Blurt.app."""
from __future__ import annotations

import subprocess
import sys
import wave
from pathlib import Path

ROOT = Path(__file__).resolve().parent.parent
SOUNDS = ROOT / "skills/blurt/recorder/macos/Sources/BlurtApp/Resources/Sounds"


def test_outputs_are_generated_from_the_sources():
    r = subprocess.run([sys.executable, str(ROOT / "assets/sounds/build.py"), "--check"], capture_output=True, text=True)
    assert r.returncode == 0, r.stdout + r.stderr


def test_every_cue_is_short_and_the_swift_names_match():
    swift = (ROOT / "skills/blurt/recorder/macos/Sources/BlurtApp/Capture/Dictation/DictationSound.swift").read_text()
    assert "case start, stop, cancel" in swift
    for name, most in (("start", 0.3), ("stop", 0.15), ("cancel", 0.1)):
        with wave.open(str(SOUNDS / f"{name}.wav")) as w:
            seconds = w.getnframes() / w.getframerate()
        # a start cue that runs on is heard by the mic it announces; a stop cue is over before the next take
        assert 0.03 < seconds <= most, (name, seconds)


def test_the_app_bundle_gets_them():
    assert '"Resources" / "Sounds"' in (ROOT / "skills/blurt/scripts/record.py").read_text()
